operation.add:
$given = isset($this->request->post['csrf_token']) ? trim((string)$this->request->post['csrf_token']) : '';

if (!$given || !$this->model_extension_module_egeser_lead_security->verifyNonce($given)) {
    $this->response->addHeader('HTTP/1.1 403 Forbidden');
    $this->response->setOutput(json_encode(array(
        'success'=>false,
        'csrf_refresh'=>true,
        'message'=>'Form güvenlik doğrulaması başarısız. Lütfen tekrar deneyin.'
    )));
    return;
}

/*
 * Legacy session-CSRF bloğunun devamındaki $given + if kontrolü
 * alttaki iki OCMOD operasyonuyla nötrlenir.
 */
$expected = '__EGESER_DB_NONCE_OK__';

if (!$this->model_extension_module_egeser_lead_security->consumeNonce($given)) {
    $this->response->addHeader('HTTP/1.1 403 Forbidden');
    $this->response->setOutput(json_encode(array(
        'success'=>false,
        'csrf_refresh'=>true,
        'message'=>'Form güvenlik anahtarı kullanılmış veya süresi dolmuş. Lütfen tekrar deneyin.'
    )));
    return;
}
